function ChapterUtils.ReplaceStr(s, pattern, replace)
    local i,j = string.find(s, pattern, 1, true)
    if i and j then
        local ret = {}
        local start = 1
        while i and j do
            table.insert(ret, string.sub(s, start, i - 1))
            table.insert(ret, replace)
            start = j + 1
            i,j = string.find(s, pattern, start, true)
        end
        table.insert(ret, string.sub(s, start))
        return table.concat(ret)
    end
    return s
end

function ChapterUtils.GetQTEs(configId)
    local qte = ChapterUtils.GetQTE(configId)
    local groups = {}
    if not isSet(groups, qte.groupId) then
        groups[qte.groupId] = {}
    end
    table.insert(groups[qte.groupId], qte)
    while true do
        if qte.next == 0 then
            break
        end
        qte = ChapterUtils.GetQTE(qte.next)
        if not isSet(groups, qte.groupId) then
            groups[qte.groupId] = {}
        end
        table.insert(groups[qte.groupId], qte)
    end


    return table.values(groups)
end

function ChapterUtils.GetQTE(configId)
    local setting = SettingMgr:GetInstance():GetSetting(AutoIds.IdSetting372, "ChapterQTEVo")
    return setting:Get(configId)
end

function ChapterUtils.ResizeContent(content, destCnt, childObj)
    local srcCnt = content.childCount
    local minusCnt = destCnt - srcCnt
    --printInfo(minusCnt)
    if minusCnt < 0 then
        minusCnt = math.abs(minusCnt)
        for i = srcCnt,srcCnt - minusCnt,-1 do
            local idx = i - 1
            KTool.SetActive(content:GetChild(idx).gameObject,false)
        end
    elseif minusCnt > 0 then
        for i = 1, minusCnt do
            GameObject.Instantiate(childObj,content)
        end
    end
    for i = 1, destCnt do
        local idx = i - 1
        KTool.SetActive(content:GetChild(idx).gameObject,true)
    end
end

