---@param generalVo ChapterGeneralVo
function ChapterUtils.PerformChapter(generalVo, onStart, onFinish, beforeFinish)
    local skipLoadingPanel = false
    local type = ChapterUtils.GetChapterTypeById(generalVo.id)
    if type == ChapterConstants.ChapterType.PreChapter then
        -- 序章不使用loading界面
        skipLoadingPanel = true
    end

    local blackWait = true
    if not skipLoadingPanel then
        GameUtils.ShowBlackOverlay(nil, function()
            while blackWait do
                coroutine.yield()
            end
        end)
    end
    
    local lights = KTool.GetDirectLightWithLayerName("role");
    local lightSt = {}
    local ResourceModule = CS.Engine.Modules.ResourceModule
    -- print("[加载] 开始加载timeline", generalVo.id, generalVo.timelinePath, CS.UnityEngine.Time.realtimeSinceStartup)
    local loader = ResourceModule.LoadBundleAsync(generalVo.timelinePath, nil, true)
    while not loader.IsCompleted do
        coroutine.yield()
    end
    -- print("[加载] 加载timeline完成", generalVo.id, generalVo.timelinePath, CS.UnityEngine.Time.realtimeSinceStartup)
    blackWait = false
    if loader.IsSuccess then
        -- local go = CS.UnityEngine.GameObject.Instantiate(loader.ResultObject)

        local go = loader:Instantiate()
        --go.transform.localPosition = CS.UnityEngine.Vector3.zero
        KTool.ResetTransform(go.transform)
        local vec = go.transform.localPosition
        -- vec.y = -100
        go.transform.localPosition = vec
        
        CriWareUtils.StopAll()
        
        GameUtils.SetBodyShadow(false)

        Events.Broadcast(Constants.EventNames.OnChapterStart, generalVo.id)

        KTool.SetActive(URPCameraController.uiCamera, false)

        if onStart ~= nil then
            printInfo("onStart")
            onStart(go)
        end
        --go:GetComponent(typeof(ChapterDirector)):PlayIndex(0)

        if not isNull(lights) then
            for i = 0, lights.Length - 1 do
                lightSt[i] = KTool.IsActiveInHierarchy(lights[i].gameObject)
                KTool.SetActive(lights[i].gameObject, false)
            end
        end
        local WaitForTimelineFinish = CS.WaitForTimelineFinish
        local PlayableDirector = CS.UnityEngine.Playables.PlayableDirector
        if not KTool.IsActiveInHierarchy(go) then
            KTool.SetActive(go, true)
        end
        ChapterUtils.CalculateScreenFit(go)
        
        --local director = go:GetComponent(typeof(PlayableDirector))
        local processor = go:GetComponentInChildren(typeof(ChapterProcessor))
        local wait = true
        processor.OnChapterFinish = function()
            wait = false
        end
        processor:PlayDirector()
        --coroutine.yield(WaitForTimelineFinish(director))
        while (wait) do
            coroutine.yield()
        end

        loader:Release()
        printInfo("finish")

        if not isNull(beforeFinish) then
            coroutine.yield(beforeFinish(generalVo))
        end
        
        CriWareUtils.StopAll()

        KTool.SetActive(URPCameraController.uiCamera, true)
        
        --ChapterUtils.ClearLipHandler(go)
        if onFinish ~= nil then
            onFinish()
        end

        if not isNull(lights) then
            for i = 0, lights.Length - 1 do
                if not isNull(lights[i]) then
                    KTool.SetActive(lights[i].gameObject, lightSt[i])
                end
            end
        end
        GameUtils.SetBodyShadow(true)
        
        Events.Broadcast(Constants.EventNames.OnChapterEnd, generalVo.id)
    else
        Events.Broadcast(Constants.EventNames.OnChapterStart, generalVo.id)
        if onStart ~= nil then
            onStart(nil)
        end
        loader:Release()
        --- 没有加载c成功直接跳过
        if onFinish ~= nil then
            onFinish()
        end
        Events.Broadcast(Constants.EventNames.OnChapterEnd, generalVo.id)
    end
end

