---写死的转场机制
function ChapterUtils.TurnChapter(generalVo, onStart, onFinish, exParameter, beforeFinish)
    local blackWait = true
    GameUtils.ShowBlackOverlay(nil, function()
        while blackWait do
            coroutine.yield()
        end
    end)
    local lights = KTool.GetDirectLightWithLayerName("role")
    local lightSt = {}
    
    Events.Broadcast(Constants.EventNames.OnChapterStart, generalVo.id)
    
    if not isNull(lights) then
        for i = 0, lights.Length - 1  do
            lightSt[i] = KTool.IsActiveInHierarchy(lights[i].gameObject)
            KTool.SetActive(lights[i].gameObject, false)
        end
    end
    
    if onStart ~= nil then
        onStart(nil)
    end

    if onFinish ~= nil then
        onFinish()
    end
    --go:GetComponent(typeof(ChapterDirector)):PlayIndex(0)
    Events.Broadcast(Constants.EventNames.OnChapterEnd, generalVo.id)

    coroutine.yield(Yielders.GetWaitForSeconds(0.2))

    local loader = ResourceModule.LoadBundleAsync(ChapterConstants.ChapterPrefabPath, nil, true)
    while not loader.IsCompleted do
        coroutine.yield()
    end
    blackWait = false
    local chapterFinish = false
    local fightLoading = false
    
    if loader.IsSuccess then
        local go = loader:Instantiate()
        loader:Release()
        go.transform.localPosition = CS.UnityEngine.Vector3.zero
        CS.UnityEngine.GameObject.DontDestroyOnLoad(go)
        
        ChapterUtils.CalculateScreenFit(go)
        
        local LuaBehaviour = CS.Engine.Modules.LuaBehaviour
        local function onRealFinish()
            --AudioManager.Instance:StopMusic()
            -- loader:Release()
            printInfo("finish")
            --if onFinish ~= nil then
            --    onFinish()
            --end
            --Events.Broadcast(Constants.EventNames.OnChapterEnd, generalVo.id)
            --wait = 
            chapterFinish = true
            blackWait = not (fightLoading and chapterFinish)
        end
        --go:GetComponent(typeof(ChapterDirector)).OnChapterFinish = onRealFinish
        --AudioManager.Instance:StopMusic()
        --if not string.isEmpty(generalVo.bgm)  then
        --    printInfo("generalVo.bgm %s", generalVo.bgm)
        --    AudioManager.Instance:PlayMusic(generalVo.bgm)
        --end
        CriWareUtils.StopAll()
        
        
        local behaviour = go:GetComponent(typeof(LuaBehaviour))
        if isNull(behaviour.Env) then
            behaviour:Init()
        end

        if exParameter == nil then
            exParameter = {}
        end
        exParameter.finishCall = onRealFinish

        behaviour.Env:StartChapter(generalVo, exParameter)

        local fightPreWarMgr = FightPreWarMgr:GetInstance()
        local data = fightPreWarMgr:GetGuideNextData()
        fightPreWarMgr:SetFightData(data, fightPreWarMgr:GetBattleArgs())
        printInfo(data.battleData.questId)

        coroutine.yield(Yielders.GetWaitForSeconds(0.2))
        
        BattleMgr = import('Game.Battle.Core.BattleMgr')
        BattleViewMgr = import('Game.BattleView.Core.BattleViewMgr')
        local wait 
        
        BattleViewMgr:RestartBattle(data.battleData, function()
            fightLoading = true
            wait = not (fightLoading and chapterFinish)
            lights = KTool.GetDirectLightWithLayerName("role");
            lightSt = {}
            if not isNull(lights) then
                for i = 0, lights.Length - 1 do
                    lightSt[i] = KTool.IsActiveInHierarchy(lights[i].gameObject)
                    KTool.SetActive(lights[i].gameObject, false)
                end
            end
        end, true)

        wait = true
        while wait do
            coroutine.yield()
        end

        if beforeFinish ~= nil then
            coroutine.yield(beforeFinish(generalVo))
        end

        KTool.SafeDelete(go)

        if not isNull(lights) then
            for i = 0, lights.Length - 1 do
                KTool.SetActive(lights[i].gameObject, lightSt[i])
            end
        end
        
        BattleViewMgr:StartBattle()
        
        
    else

        loader:Release()
        --- 没有加载c成功直接跳过
        BattleMgr = import('Game.Battle.Core.BattleMgr')
        BattleViewMgr = import('Game.BattleView.Core.BattleViewMgr')
        
        local fightPreWarMgr = FightPreWarMgr:GetInstance()
        local data = fightPreWarMgr:GetGuideNextData()
        fightPreWarMgr:SetFightData(data, fightPreWarMgr:GetBattleArgs())
        
        BattleViewMgr:RestartBattle(data)
        
    end
    
    
end

--- 默认QTE的播放方式(如果需要更高级的QTE，就在预制体上加自定义的Player脚本)
---@param go any
function ChapterUtils.TimelineCustomPlay(go)
    local bambooPlayer = AddLuaBehaviour(go, "Game.Chapter.BambooPlayer")
    if isNull(bambooPlayer.Env) then
        bambooPlayer:Init()
    end
    local env = bambooPlayer.Env
    local uiCamera = go.transform:Find("UICameraTop").gameObject:GetComponentInChildren(typeof(CS.UnityEngine.Camera))
    local chapterNewUI = uiCamera.transform:GetChild(0):Find("ChapterNewUI")
    local touchRoot = chapterNewUI:Find("CatQTE")   -- 默认的QTEUI根节点名字叫CatQTE，UI可以随便改，保证根节点名字都叫CatQTE就能生效
    if touchRoot then
        local touchArea = touchRoot:GetChild(0):Find("Area")
        env:SetCustomTouchHandler(touchRoot.gameObject, touchArea.gameObject)
    end
    env:Initialize()
    env:StartPlay()
end

--- 剧情配的QTE走这个接口
---（如果代码直接调用可以用StartExternalChapter接口，然后onCustomPlay参数传ChapterUtils.TimelineCustomPlay）
---@param generalVo any
---@param onStart any
---@param onFinish any
---@param exParameter any
function ChapterUtils.QTEChapter(generalVo, onStart, onFinish, exParameter, beforeFinish)
    local timelinePath = generalVo.timelinePath
    local onCustomPlay = ChapterUtils.TimelineCustomPlay

    return cs_coroutine.start(function()
        local loader = ResourceModule.GetLoaderByURL(timelinePath)

        -- print("[加载] 开始加载timeline", generalVo.id, generalVo.timelinePath, CS.UnityEngine.Time.realtimeSinceStartup)
        if isNull(loader) then
            loader = ResourceModule.LoadBundleAsync(timelinePath, nil, true)
        end

        while not loader.IsCompleted do
            coroutine.yield()
        end
        -- print("[加载] 加载timeline完成", generalVo.id, generalVo.timelinePath, CS.UnityEngine.Time.realtimeSinceStartup)
        if not loader.IsSuccess then

            if onStart ~= nil then
                onStart(nil, loader)
            end

            if onFinish ~= nil then
                onFinish()
            end
            
            return
        end

        local go = CS.UnityEngine.GameObject.Instantiate(loader.ResultObject)
        local processor = go:GetComponentInChildren(typeof(ChapterProcessor))

        ChapterUtils.CalculateScreenFit(go)

        local wait = true
        processor.OnChapterFinish = function()
            wait = false
        end

        -- 可以在timeline预制体上挂在自定义脚本
        local behaviour = go:GetComponent(typeof(LuaBehaviour))
        if behaviour and isNull(behaviour.Env) then
            behaviour:Init()
        end
        
        if onStart ~= nil then
            URPCameraController:SetMainCameraActive(false)  -- 自带相机，需要关闭主相机
            KTool.SetActive(URPCameraController.uiCamera, false)

            -- 自定义的onStart
            if behaviour and behaviour.Env.OnChapterStart then
                behaviour.Env:OnChapterStart(generalVo, exParameter)
            end

            onStart(go, loader)
        end

        -- 决定QTE播放方式的回调
        if behaviour and behaviour.Env.OnCustomPlay then
            behaviour.Env:OnCustomPlay(generalVo, exParameter)
        else
            if onCustomPlay ~= nil then
                onCustomPlay(go)
            else
                processor:PlayDirector()
            end
        end

        while wait do
            coroutine.yield()
        end

        if beforeFinish ~= nil then
            coroutine.yield(beforeFinish(generalVo))
        end

        --ChapterUtils.ClearLipHandler(go)
        if onFinish ~= nil then
            URPCameraController:SetMainCameraActive(true)  -- 自带相机，需要关闭主相机
            KTool.SetActive(URPCameraController.uiCamera, true)
            
            onFinish(go)
            if not isNull(go) then
                CS.UnityEngine.GameObject.Destroy(go)
            end
        end
    end)
end

function ChapterUtils.CalculateScreenFit(go)
    local tmp = go:GetComponentsInChildren(typeof(CS.UnityEngine.UI.CanvasScaler), true)
    if isNull(tmp) then
        return
    end

    for i = 1, tmp.Length do
        local scaler = tmp[i - 1]
        if not string.contains(scaler.transform.parent.name, "_mov") then
            KTool.CalculateScreenFit(scaler)
        end
    end
    printInfo("calc")
end

function ChapterUtils.ClearLipHandler(go)
    local lips = go:GetComponentsInChildren(typeof(CriLipsDeformerForAtomSource), true)
    if not isNull(lips) then
        for i = 1, lips.Length do
            local tmp = lips[i - 1]
            if not isNull(tmp.atomAnalyzer) then
                tmp.atomAnalyzer:Dispose()
            end
        end
    end
end


