function ChapterUtils.TestBambooChapter(onStart, onFinish)
    local timelinePath = "ChapterNew/stage_bamboo.prefab"
    local onCustomPlay = function(go)
        local bambooPlayer = GetLuaBehaviour(go, "Game.Chapter.BambooPlayer")
        if isNull(bambooPlayer.Env) then
            bambooPlayer:Init()
        end
        local env = bambooPlayer.Env
        env:Initialize()
        env:StartPlay()
    end
    ChapterUtils.StartExternalChapter(timelinePath, onStart, onFinish, onCustomPlay)
end

---@param onStart fun(loader:Engine.Modules.AbstractResourceLoader, go:UnityEngine.GameObject)
---@param onFinish fun()
---@param onCustomPlay fun(go:UnityEngine.GameObject)
---@return UnityEngine.Coroutine
function ChapterUtils.StartExternalChapter(timelinePath, onStart, onFinish, onCustomPlay)
    return cs_coroutine.start(function()
        local loader = ResourceModule.GetLoaderByURL(timelinePath)

        if isNull(loader) then
            loader = ResourceModule.LoadBundleAsync(timelinePath, nil, true)
        end

        while not loader.IsCompleted do
            coroutine.yield()
        end
        if not loader.IsSuccess then

            if onStart ~= nil then
                onStart(loader, nil)
            end

            if onFinish ~= nil then
                onFinish()
            end
            
            return
        end

        local go = CS.UnityEngine.GameObject.Instantiate(loader.ResultObject)
        local processor = go:GetComponentInChildren(typeof(ChapterProcessor))

        ChapterUtils.CalculateScreenFit(go)

        local wait = true
        processor.OnChapterFinish = function()
            wait = false
        end
        
        if onStart ~= nil then
            onStart(loader, go)
        end

        if onCustomPlay ~= nil then
            onCustomPlay(go)
        else
            processor:PlayDirector()
        end

        while wait do
            coroutine.yield()
        end

        --ChapterUtils.ClearLipHandler(go)
        if onFinish ~= nil then
            onFinish(go)
        end
    end)
end

function ChapterUtils.GetChapterTypeById(id)
    if id >= 3007000 and id <= 3007350 then
        return ChapterConstants.ChapterType.Normal
    elseif id >= 1000010 or id <= 1000190 then
        return ChapterConstants.ChapterType.PreChapter
    elseif id >= 200000000 and id < 300000000 then
        return ChapterConstants.ChapterType.RolePlot
    elseif id >= 400000 and id < 500000 then
        return ChapterConstants.ChapterType.PrePlot
    elseif id >= 1000000 and id < 1000010 then
        return ChapterConstants.ChapterType.PreDownload
    elseif id >= 3000000 or id < 4000000 then
        return ChapterConstants.ChapterType.DungeonPlot
    end
    return ChapterConstants.ChapterType.Normal
end

function ChapterUtils.GetSettingPathById(id)
    local key = "IdSetting" .. id
    if not isSet(ChapterAutoIds, key) then
        printError("auto id not found %s", key)
    end
    return ChapterAutoIds[key]
end

function ChapterUtils.WillTriggerSpecialExits(id)
    local t = nil
    for i, v in pairs(ChapterConstants.SpecialExits) do
        if v.id == id then
            t = v
            break
        end
    end
    
    local st = t ~= nil
    return st, t
end

function ChapterUtils.TriggerSpecialExit(tb)
    return cs_coroutine.start(function() 
        
        local finish = false
        local cacheGo = nil
        ChapterUtils.ProcessChapter(tb.chapterId, function(go)
            cacheGo = go
            if not isNull(go) then
                CS.UnityEngine.GameObject.DontDestroyOnLoad(go)
            end
        end, function()
            KTool.SafeDelete(cacheGo)

            finish = true
        end)

        while not finish do
            coroutine.yield(Yielders.EndOfFrame)
        end

        GameUtils.ShowBlackOverlay()
        GameUtils.OpenLoadingPanel({ id = Constants.UITypeIds.UISceneHome, hasExcluded = false }, nil, Constants.LoadingType.MainHome)


    end)
end

--- 收集transform下面所有控制嘴部的骨骼
---@param transform any
function ChapterUtils.CollectMouseRig(transform)
    local result = {}
    
    xTry(function()
        for i, rigName in ipairs(MouseRigName) do
            local rig = transform:Find(string.format(MouseRigPath, rigName))
            table.insert(result, rig)
        end
    end, function()
        printError(string.format("[嘴型] %s 模型不是美术标准的骨骼层级结构", transform.name))
    end)
    
    if Config.DEBUG then
        local isOK = ChapterUtils.VerifyMouseRig(result)
        -- print("[嘴型] 骨骼收集", transform.name, isOK, table.dump(result))
        
        if not isOK then
            result = {}
        end
    end

    return result
end

function ChapterUtils.VerifyMouseRig(rigs)
    if table.count(rigs) == 0 then
        return false
    end
    return true
end

return ChapterUtils
